import time

class UpstreamTimeout(Exception):
    pass

def with_retry(fn, attempts=3, base=0.01):
    delays = []
    for i in range(attempts):
        try:
            return fn(i), delays
        except UpstreamTimeout:
            delays.append(round(base * (2 ** i), 3))
            time.sleep(delays[-1])
    raise RuntimeError("gave up: upstream down")

def flaky(i):
    if i < 2:
        raise UpstreamTimeout("read timeout")
    return "ok"

print(with_retry(flaky))
print(with_retry(lambda i: "first try", attempts=1))

import json
from datetime import datetime, timezone

def envelope(result=None, error=None, request_id="req-1"):
    body = {
        "request_id": request_id,
        "ts": datetime(2026, 1, 1, tzinfo=timezone.utc).isoformat(),
    }
    if error:
        body.update({"ok": False, "error": {"code": "invalid_request", "message": error}})
    else:
        body.update({"ok": True, "data": result})
    return body

print(json.dumps(envelope(result={"answer": "hi", "sources": ["d2"]})))
print(json.dumps(envelope(error="text required")))

