REQUIRED = {"DATABASE_URL": str, "MODEL_PATH": str, "WORKERS": int}

def load_config(env):
    problems, cfg = [], {}
    for key, typ in REQUIRED.items():
        val = env.get(key)
        if val is None:
            problems.append(f"{key}: missing")
            continue
        try:
            cfg[key] = typ(val)
        except (TypeError, ValueError):
            problems.append(f"{key}: expected {typ.__name__}")
    if problems:
        raise RuntimeError("config invalid: " + "; ".join(problems))
    return cfg

try:
    load_config({"DATABASE_URL": "postgres://x"})
except RuntimeError as e:
    print(e)
print(load_config({"DATABASE_URL": "postgres://x", "MODEL_PATH": "/m", "WORKERS": "4"}))

from dataclasses import dataclass, field

@dataclass
class Probe:
    name: str
    checks: list = field(default_factory=list)

    def run(self, deps):
        results = [(c, bool(deps.get(c))) for c in self.checks]
        return {"ok": all(v for _, v in results), "detail": results}

liveness = Probe("liveness", ["process_alive"])
readiness = Probe("readiness", ["process_alive", "db_ping", "vector_index"])
deps = {"process_alive": True, "db_ping": False, "vector_index": True}

print(liveness.run(deps))
print(readiness.run(deps))
print("send traffic:", "yes" if readiness.run(deps)["ok"] else "no")
